                'email' => 'KARLALORENA.RIVERATAPIA@GMAIL.COM',
            ],
        ];

        foreach ($patients as $data) {
             // 1. Determine Identity (RUT or Name)
             $criteria = [];
             
             if (!empty($data['rut'])) {
                 $criteria['rut'] = $data['rut'];    
             } else {
                 $criteria['name'] = $data['name'];
                 $criteria['last_name'] = $data['last_name'];
                 // If name/lastname are not unique enough, we might have issues, 
                 // but without RUT it's the best we have.
             }

             // 2. Use withoutGlobalScopes to match ANY existing patient (even in Co 1)
             // 3. Update them to Co 2 (defined in $data)
             
             $patient = Patient::withoutGlobalScopes()->updateOrCreate(
                $criteria,
                $data // This contains 'company_id' => 2
            );

            // 4. Sync Branch
            $patient->branches()->syncWithoutDetaching([2]);
        }
    }
}
